import React from 'react';
import { motion } from 'framer-motion';

interface AnimatedTextProps {
  text: string;
  className?: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div';
  preserveWhitespace?: boolean;
  onAnimationComplete?: () => void;
}

/**
 * AnimatedText - A component that renders text with a character-by-character animation
 * similar to Claude's interface.
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  className = '',
  element = 'p',
  preserveWhitespace = false,
  onAnimationComplete
}) => {
  // Split text into individual characters
  const characters = Array.from(text);

  // Animation container variant
  const container = {
    hidden: {},
    visible: {
      transition: {
        staggerChildren: 0.018, // Base character delay - Claude-like
        staggerDirection: 1,
        delayChildren: 0.01,
        when: 'beforeChildren'
      }
    }
  };

  // Character animation variant
  const child = {
    hidden: { 
      opacity: 0,
      display: 'inline-block'
    },
    visible: { 
      opacity: 1,
      display: 'inline-block',
      transition: { 
        duration: 0.01, // Very quick appearance like Claude
        ease: "linear"
      }
    }
  };

  // Characters with slightly longer pauses after them
  const punctuation = ['.', ',', '!', '?', ':', ';'];

  // Apply a bit longer pause after punctuation to mimic natural typing
  const getCharacterDelay = (char: string, index: number) => {
    if (punctuation.includes(char)) {
      return 2.5; // Longer delay factor after punctuation
    }
    return 1; // Normal delay
  };

  // Create the characters as motion.span elements
  const animatedCharacters = characters.map((char, index) => (
    <motion.span
      key={`${index}-${char}`}
      variants={child}
      custom={getCharacterDelay(char, index)}
      transition={{
        delay: punctuation.includes(char) ? 0.05 : 0,
        staggerMultiplier: getCharacterDelay(char, index)
      }}
    >
      {char === ' ' ? '\u00A0' : char}
    </motion.span>
  ));

  // Render the appropriate element with the animated characters
  const commonProps = {
    className: `animated-text ${className}`,
    style: { whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const },
    variants: container,
    initial: "hidden",
    animate: "visible",
    onAnimationComplete
  };

  switch (element) {
    case 'h1':
      return <motion.h1 {...commonProps}>{animatedCharacters}</motion.h1>;
    case 'h2':
      return <motion.h2 {...commonProps}>{animatedCharacters}</motion.h2>;
    case 'h3':
      return <motion.h3 {...commonProps}>{animatedCharacters}</motion.h3>;
    case 'h4':
      return <motion.h4 {...commonProps}>{animatedCharacters}</motion.h4>;
    case 'span':
      return <motion.span {...commonProps}>{animatedCharacters}</motion.span>;
    case 'div':
      return <motion.div {...commonProps}>{animatedCharacters}</motion.div>;
    case 'p':
    default:
      return <motion.p {...commonProps}>{animatedCharacters}</motion.p>;
  }
};

export default AnimatedText;
